/* Canonical: CoD4x_Client_pub/src/recoil/sim.h (MIT; see its LICENSE.md).
 * Server mirror is GENERATED by tools/sync-recoil.py; do not edit the mirror.
 *
 * Deterministic view-kick simulation shared by client prediction and the server, and the interface recoil
 * models implement (docs/recoil-models.md). Integer only, so both builds agree bit for bit: angles in
 * micro-degrees, speeds in milli-degrees per second (= micro-degrees per millisecond). Recovery runs in stock
 * 5 ms slices on a grid of absolute usercmd time, so the result does not depend on how time is split into
 * usercmds, and kick strength no longer depends on frame rate (stock integrates per frame: the same kick peaks
 * 1.37 deg at 125 fps and 1.29 at 333; the grid gives 1.35). Engine glue reads its inputs via engine.h. */
#ifndef COD4X_RECOIL_SIM_H
#define COD4X_RECOIL_SIM_H

#include <stdint.h>
#include <string.h>

enum { RECOIL_SCALE = 10000, RECOIL_AXES = 3, RECOIL_CEILING = 10000000, RECOIL_IDLE_CENTER = 2400,
       RECOIL_STEP_MSEC = 5, RECOIL_MAX_GAP = 2000, RECOIL_HIP = 0, RECOIL_ADS = 1 };

typedef struct { int32_t angle[RECOIL_AXES], speed[RECOIL_AXES]; } recoil_kick_t; /* pitch, yaw, roll */

typedef struct {
    uint32_t time;          /* raw usercmd time of the last advance; 0 = unset */
    recoil_kick_t kick;
    uint64_t model[4];      /* private to the active model */
} recoil_sim_t;

/* Native view-kick data of one weapon, converted once from WeaponDef by Recoil_WeaponKick. */
typedef struct {
    int32_t pitch[2][2], yaw[2][2]; /* [hip|ads][min|max], mdeg/s */
    int32_t center[2];              /* [hip|ads] return acceleration, deg/s^2 */
    int32_t reduced[2];             /* [hip|ads] native reduced-kick scale, basis points */
    uint32_t fire_msec;
} recoil_weapon_kick_t;

/* Inputs for recovery, sampled from the player state before the usercmd (Recoil_SampleStep). */
typedef struct {
    uint32_t weapon;                    /* 0 = none */
    const recoil_weapon_kick_t *def;    /* NULL = none */
    uint8_t ads_half, alive;            /* fWeaponPosFrac > 0.5; the player's own live state */
} recoil_step_t;

/* One fire event, sampled from the player state after the usercmd's Pmove (Recoil_SampleShot). */
typedef struct {
    uint32_t time, shooter, index, weapon;  /* raw usercmd time, client, order within the usercmd */
    const recoil_weapon_kick_t *def;
    uint8_t ads_full, reduced;              /* fWeaponPosFrac == 1; weaponRestrictKickTime > 0 */
} recoil_shot_t;

typedef struct {
    int32_t view[RECOIL_AXES];  /* view-kick speeds the shot sets */
    uint32_t gun_scale;         /* basis points applied to the native gun kick */
} recoil_shot_result_t;

/* One per-weapon profile integer: the wire decoder enforces [min, max]. */
typedef struct { const char *name; uint32_t min, max; } recoil_param_t;

/* A model: its per-weapon parameters, and hooks that adjust the native behaviour. Every hook is optional and
 * runs only for weapons with a profile entry; validate checks rules spanning several parameters. Add a model in
 * recoil/models/ and register it in model.h. */
typedef struct {
    uint32_t id; const char *name;
    const recoil_param_t *params; uint32_t param_count;
    int (*validate)(const uint32_t *param);
    void (*shot)(recoil_sim_t *, const uint32_t *param, const recoil_shot_t *, recoil_shot_result_t *);
    void (*step)(recoil_sim_t *, const uint32_t *param, const recoil_step_t *); /* one 5 ms slice */
} recoil_model_t;

static inline uint64_t Recoil_Mix(uint64_t value)
{
    value += UINT64_C(0x9E3779B97F4A7C15);
    value = (value ^ (value >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
    value = (value ^ (value >> 27)) * UINT64_C(0x94D049BB133111EB);
    return value ^ (value >> 31);
}

/* History-free: one disputed shot never shifts another (ScrapCore counter_hash). */
static inline uint64_t Recoil_Hash(uint64_t domain, const recoil_shot_t *shot)
{
    uint64_t hash = domain;
    hash = Recoil_Mix(hash ^ Recoil_Mix(shot->shooter));
    hash = Recoil_Mix(hash ^ Recoil_Mix(shot->time));
    hash = Recoil_Mix(hash ^ Recoil_Mix(shot->index));
    return Recoil_Mix(hash ^ Recoil_Mix(shot->weapon));
}

/* Uniform in [a, b] with 24 bits of resolution, like the native lerp over randomf(). */
static inline int32_t Recoil_Sample(int32_t a, int32_t b, uint64_t hash)
{
    return a + (int32_t)((int64_t)(b - a) * (int64_t)(hash >> 40) / (INT64_C(1) << 24));
}

/* Rounds half away from zero. Exact for every float: value * 1000 fits a double's mantissa. */
static inline int32_t Recoil_Fixed(float value, double unit)
{
    const double scaled = (double)value * unit;
    return (int32_t)(scaled < 0 ? -(int64_t)(0.5 - scaled) : (int64_t)(scaled + 0.5));
}

/* hip and ads point at WeaponDef's five consecutive floats: PitchMin, PitchMax, YawMin, YawMax, CenterSpeed. */
static inline void Recoil_WeaponKick(recoil_weapon_kick_t *out, const float *hip, const float *ads,
    float hip_reduced_percent, float ads_reduced_percent, int fire_msec)
{
    const float *ranges[2] = {hip, ads};
    int i;
    for (i = 0; i < 2; ++i) {
        out->pitch[i][0] = Recoil_Fixed(ranges[i][0], 1000.0);
        out->pitch[i][1] = Recoil_Fixed(ranges[i][1], 1000.0);
        out->yaw[i][0] = Recoil_Fixed(ranges[i][2], 1000.0);
        out->yaw[i][1] = Recoil_Fixed(ranges[i][3], 1000.0);
        out->center[i] = Recoil_Fixed(ranges[i][4], 1.0);
    }
    out->reduced[RECOIL_HIP] = Recoil_Fixed(hip_reduced_percent, 100.0);
    out->reduced[RECOIL_ADS] = Recoil_Fixed(ads_reduced_percent, 100.0);
    out->fire_msec = fire_msec > 0 ? (uint32_t)fire_msec : 0;
}

/* BG_WeaponFireRecoil's view kick (server _bg_weapons.asm:2180): ADS ranges only at full ADS, the reduced
 * window scales it, roll is half the yaw, reversed; randomf() replaced by Recoil_Hash. */
static inline recoil_shot_result_t Recoil_NativeShot(const recoil_shot_t *shot)
{
    recoil_shot_result_t r;
    const int mode = shot->ads_full ? RECOIL_ADS : RECOIL_HIP;
    const int64_t scale = shot->reduced ? shot->def->reduced[mode] : RECOIL_SCALE;
    const int32_t pitch = Recoil_Sample(shot->def->pitch[mode][0], shot->def->pitch[mode][1],
                                        Recoil_Hash(UINT64_C(0x5049544348), shot));
    const int32_t yaw = Recoil_Sample(shot->def->yaw[mode][0], shot->def->yaw[mode][1],
                                      Recoil_Hash(UINT64_C(0x594157), shot));
    r.view[0] = (int32_t)(-pitch * scale / RECOIL_SCALE);
    r.view[1] = (int32_t)(yaw * scale / RECOIL_SCALE);
    r.view[2] = -r.view[1] / 2;
    r.gun_scale = RECOIL_SCALE;
    return r;
}

/* One 5 ms slice of CG_KickAngles (client bin 0x44FE20, facts file): accelerate toward centre, damp the
 * return to 6%, rest on crossing zero, clamp at 10 degrees. */
static inline void Recoil_NativeStep(recoil_sim_t *sim, const recoil_step_t *step)
{
    const int32_t center = step->def ? step->def->center[step->ads_half ? RECOIL_ADS : RECOIL_HIP]
                                     : RECOIL_IDLE_CENTER;
    int i;
    for (i = 0; i < RECOIL_AXES; ++i) {
        int32_t *angle = &sim->kick.angle[i], *speed = &sim->kick.speed[i];
        int32_t change, next;
        if (!*angle && !*speed) continue;
        if (*angle) *speed += (*angle > 0 ? -center : center) * RECOIL_STEP_MSEC;
        change = *speed * RECOIL_STEP_MSEC;
        if ((*angle > 0 && change < 0) || (*angle < 0 && change > 0)) change = change * 6 / 100;
        next = *angle + change;
        if ((*angle > 0 && next < 0) || (*angle < 0 && next > 0) || !next) {
            *angle = *speed = 0;
        } else if (next > RECOIL_CEILING || next < -RECOIL_CEILING) {
            *angle = next > 0 ? RECOIL_CEILING : -RECOIL_CEILING;
            *speed = 0;
        } else {
            *angle = next;
        }
    }
}

static inline int Recoil_AtRest(const recoil_sim_t *sim)
{
    static const recoil_kick_t rest;
    return !memcmp(&sim->kick, &rest, sizeof(rest));
}

static inline void Recoil_Reset(recoil_sim_t *sim, uint32_t time)
{
    memset(sim, 0, sizeof(*sim));
    sim->time = time;
}

/* Recover to raw usercmd time: one slice per grid boundary crossed, so any split of the interval agrees.
 * param is the step weapon's profile entry (NULL: native recovery). */
static inline void Recoil_Advance(recoil_sim_t *sim, const recoil_model_t *model, const uint32_t *param,
    const recoil_step_t *step, uint32_t time)
{
    const uint32_t elapsed = time - sim->time;
    uint32_t slices = time / RECOIL_STEP_MSEC - sim->time / RECOIL_STEP_MSEC;
    if (!sim->time || elapsed > INT32_MAX || !step->alive) { Recoil_Reset(sim, time); return; }
    if (elapsed > RECOIL_MAX_GAP) memset(&sim->kick, 0, sizeof(sim->kick));
    for (; slices && !Recoil_AtRest(sim); --slices) {
        if (param && model->step) model->step(sim, param, step);
        else Recoil_NativeStep(sim, step);
    }
    sim->time = time;
}

/* A fire event: the native kick, adjusted by the model for profiled weapons, sets the view-kick speed. */
static inline recoil_shot_result_t Recoil_Shot(recoil_sim_t *sim, const recoil_model_t *model,
    const uint32_t *param, const recoil_shot_t *shot)
{
    recoil_shot_result_t r = Recoil_NativeShot(shot);
    if (param && model->shot) model->shot(sim, param, shot, &r);
    memcpy(sim->kick.speed, r.view, sizeof(sim->kick.speed));
    return r;
}

/* The server's correction message (svc_recoil): the whole state as 32-bit words, in this order. */
enum { RECOIL_PACKED = 15 }; /* time, angle[3], speed[3], model[4] as low/high halves */
typedef char recoil_packed_fits[RECOIL_PACKED == 1 + 2 * RECOIL_AXES + 2 * 4 ? 1 : -1];
static inline void Recoil_Pack(const recoil_sim_t *sim, uint32_t out[RECOIL_PACKED])
{
    int i, n = 0;
    out[n++] = sim->time;
    for (i = 0; i < RECOIL_AXES; ++i) out[n++] = (uint32_t)sim->kick.angle[i];
    for (i = 0; i < RECOIL_AXES; ++i) out[n++] = (uint32_t)sim->kick.speed[i];
    for (i = 0; i < 4; ++i) { out[n++] = (uint32_t)sim->model[i]; out[n++] = (uint32_t)(sim->model[i] >> 32); }
}

static inline void Recoil_Unpack(recoil_sim_t *sim, const uint32_t in[RECOIL_PACKED])
{
    int i, n = 0;
    sim->time = in[n++];
    for (i = 0; i < RECOIL_AXES; ++i) sim->kick.angle[i] = (int32_t)in[n++];
    for (i = 0; i < RECOIL_AXES; ++i) sim->kick.speed[i] = (int32_t)in[n++];
    for (i = 0; i < 4; ++i) { sim->model[i] = in[n] | (uint64_t)in[n + 1] << 32; n += 2; }
}

/* The view kick in usercmd angle units (65536 per turn), rounded to nearest. Both sides add exactly this. */
static inline void Recoil_Offset(const recoil_sim_t *sim, int32_t out[RECOIL_AXES])
{
    int i;
    for (i = 0; i < RECOIL_AXES; ++i) {
        const int64_t scaled = (int64_t)sim->kick.angle[i] * 65536;
        out[i] = (int32_t)((scaled + (scaled < 0 ? -180000000 : 180000000)) / 360000000);
    }
}

#endif
